import sys
sys.path.append('storage/ariadne')

import optax
from models_mlp_global_uv import create_network as create_net_uv, _define_hyperparameters as _def_uv

def _define_hyperparameters():
    hp = _def_uv()
    hp['rank_k'] = 384
    hp['proj_rank'] = 32
    hp['dropout_rate'] = 0.10
    return hp

def compute_loss(predictions, targets, params, x):
    # curvature λ=1e-4 (same as best runs)
    import losses
    return losses.mae_with_temporal_curvature(predictions, targets, params, x, lam=1e-4)

def create_network(hparams):
    return create_net_uv(hparams)

def create_optimizer(learning_rate: float = 0.001):
    return optax.chain(
        optax.clip_by_global_norm(1.0),
        optax.adamw(learning_rate=learning_rate, weight_decay=1e-4, eps=1e-8)
    )
